for vid in 98111 98112 98113 98114 98115 98116 98118; do echo "=== version $vid ==="; curl -s "https://api.box.com/2.0/file_versions/$vid" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
try:
    d=json.load(sys.stdin)
    if 'error' in str(d)[:100].lower() and 'message' in d: print(d.get('message'), d.get('type'))
    else: print(json.dumps(d, indent=1))
except Exception as e: print('ERR', e)
"; done

